<?php
declare(strict_types=1);namespace MiniErp\Platform;use PDO;use RuntimeException;use Throwable;final class MultiTenantOperationRepository{public function __construct(private PDO $pdo){}public function createPlan(int $adminId,array $migration,array $tenantIds,array $simulation,int $ttl=600):string{$id=bin2hex(random_bytes(16));$s=$this->pdo->prepare('INSERT INTO platform_migration_plans(plan_id,admin_id,migration_id,checksum,tenant_ids_json,simulation_json,created_at,expires_at) VALUES(?,?,?,?,?,?,NOW(),DATE_ADD(NOW(),INTERVAL ? SECOND))');$s->execute([$id,$adminId,$migration['migration_id'],$migration['checksum'],json_encode(array_values($tenantIds),JSON_THROW_ON_ERROR),json_encode($simulation,JSON_THROW_ON_ERROR),$ttl]);return$id;}public function consumePlan(string $id,int $adminId):array{$own=!$this->pdo->inTransaction();if($own)$this->pdo->beginTransaction();else$this->pdo->exec('SAVEPOINT consume_plan');try{$s=$this->pdo->prepare('SELECT * FROM platform_migration_plans WHERE plan_id=? AND admin_id=? FOR UPDATE');$s->execute([$id,$adminId]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p||$p['consumed_at']!==null||strtotime($p['expires_at'])<=time())throw new RuntimeException('Plano invÃ¡lido, expirado ou consumido.');$u=$this->pdo->prepare('UPDATE platform_migration_plans SET consumed_at=NOW() WHERE plan_id=? AND consumed_at IS NULL');$u->execute([$id]);if($u->rowCount()!==1)throw new RuntimeException('Plano jÃ¡ consumido.');if($own)$this->pdo->commit();else$this->pdo->exec('RELEASE SAVEPOINT consume_plan');$p['tenant_ids']=json_decode($p['tenant_ids_json'],true,512,JSON_THROW_ON_ERROR);$p['simulation']=json_decode($p['simulation_json'],true,512,JSON_THROW_ON_ERROR);return$p;}catch(Throwable $e){if($own&&$this->pdo->inTransaction())$this->pdo->rollBack();elseif(!$own)$this->pdo->exec('ROLLBACK TO SAVEPOINT consume_plan');throw$e;}}public function createOperation(array $p,array $m,string $reason):string{$id=bin2hex(random_bytes(16));$s=$this->pdo->prepare("INSERT INTO platform_database_operations(operation_id,plan_id,admin_id,migration_id,checksum,risk,reason,created_at,started_at,status) VALUES(?,?,?,?,?,?,?,NOW(),NOW(),'RUNNING')");$s->execute([$id,$p['plan_id'],$p['admin_id'],$m['migration_id'],$m['checksum'],$m['risk'],$reason]);return$id;}public function addTarget(string $op,int $tenant,string $db,string $status):void{$this->pdo->prepare('INSERT INTO platform_database_operation_targets(operation_id,tenant_id,db_name,status) VALUES(?,?,?,?)')->execute([$op,$tenant,$db,$status]);}public function target(string $op,int $tenant,string $status,array $data=[]):void{$sets=['status=?'];$params=[$status];foreach(['backup_path','backup_size','backup_sha256','duration_ms','validation_json','error_message']as$key)if(array_key_exists($key,$data)){$sets[]="$key=?";$params[]=$data[$key];}if($status==='RUNNING')$sets[]='started_at=NOW()';elseif(in_array($status,['SUCCESS','FAILED','VALIDATION_FAILED','BACKUP_FAILED','BLOCKED'],true))$sets[]='finished_at=NOW()';$params[]=$op;$params[]=$tenant;$this->pdo->prepare('UPDATE platform_database_operation_targets SET '.implode(',',$sets).' WHERE operation_id=? AND tenant_id=?')->execute($params);}public function finish(string $op,string $status):void{$this->pdo->prepare('UPDATE platform_database_operations SET status=?,finished_at=NOW() WHERE operation_id=?')->execute([$status,$op]);}public function history():array{return$this->pdo->query("SELECT o.*,a.name admin_name,(SELECT COUNT(*) FROM platform_database_operation_targets t WHERE t.operation_id=o.operation_id) tenant_count,(SELECT COUNT(*) FROM platform_database_operation_targets t WHERE t.operation_id=o.operation_id AND t.status='SUCCESS') successes FROM platform_database_operations o JOIN platform_admin_users a ON a.id=o.admin_id ORDER BY o.created_at DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);}}
